// Keeps only items at or below their reorder point. Everything else is dropped
// here, so the digest never lists an item that does not need ordering.
// suggested_order aims at twice the reorder point: enough to cover a normal
// delivery cycle without turning the stockroom into a warehouse.
const out = [];
for (const item of $input.all()) {
  const p = item.json;
  const stock = Number(p.stock);
  const point = Number(p.reorder_point);
  if (!Number.isFinite(stock) || !Number.isFinite(point)) continue;
  if (stock > point) continue;

  const use = Number(p.daily_usage);
  const days = Number.isFinite(use) && use > 0 ? Math.floor(stock / use) : null;

  out.push({
    json: {
      sku: String(p.sku || '').trim(),
      item: String(p.item || '').trim(),
      supplier: String(p.supplier || '').trim() || 'Unassigned',
      stock: stock,
      reorder_point: point,
      days_left: days,
      shortfall: point - stock,
      suggested_order: Math.max(1, Math.ceil(point * 2 - stock))
    }
  });
}

// Fewest days of stock first: that is the order you actually place them in.
out.sort(function (a, b) {
  const da = a.json.days_left === null ? 9999 : a.json.days_left;
  const db = b.json.days_left === null ? 9999 : b.json.days_left;
  return da - db;
});
return out;

// Decides whether today's digest is worth sending at all.
// State lives in the workflow's static data, so no extra sheet or credential is
// needed. It is only written after a successful send (see Record Sent), which
// keeps "already announced" honest: an item that was never sent is never marked
// as known.
const cfg = $('CONFIG').first().json;
const cadence = Math.max(1, Number(cfg.remind_every_days) || 3);
const store = $getWorkflowStaticData('global');
const known = new Set((Array.isArray(store.known) ? store.known : []).map(String));

const rows = $input.all().map(function (i) { return i.json; });
if (rows.length === 0) {
  return [{ json: { items: [], new_count: 0, ongoing_count: 0, should_send: false, reason: 'nothing low' } }];
}

let fresh = 0;
const items = rows.map(function (r) {
  const isNew = !known.has(String(r.sku));
  if (isNew) fresh++;
  return Object.assign({}, r, { is_new: isNew });
});

let reason = '';
let send = false;
const lastStamp = store.last_sent ? new Date(String(store.last_sent) + 'T00:00:00Z').getTime() : null;
if (!Number.isFinite(lastStamp)) {
  send = true;
  reason = 'first run';
} else {
  const gap = Math.floor((Date.now() - lastStamp) / 86400000);
  if (fresh > 0) {
    send = true;
    reason = fresh + ' new item' + (fresh === 1 ? '' : 's');
  } else if (gap >= cadence) {
    send = true;
    reason = 'reminder after ' + gap + ' days';
  } else {
    reason = 'no change since ' + new Date(lastStamp).toISOString().slice(0, 10);
  }
}

return [{
  json: {
    items: items,
    new_count: fresh,
    ongoing_count: items.length - fresh,
    should_send: send,
    reason: reason
  }
}];

// The unit of action is a purchase order, not a SKU. Grouping by supplier means
// one section of the message can be forwarded as-is to the person who orders.
const order = [];
const groups = new Map();

for (const item of $input.all()) {
  const p = item.json;
  const key = String(p.supplier || 'Unassigned');
  let g = groups.get(key);
  if (!g) {
    g = { supplier: key, rows: [], new_count: 0, min_days: 9999 };
    groups.set(key, g);
    order.push(key);
  }
  g.rows.push({
    sku: p.sku,
    item: p.item,
    stock: p.stock,
    reorder_point: p.reorder_point,
    days_left: p.days_left,
    suggested_order: p.suggested_order,
    is_new: p.is_new === true
  });
  if (p.is_new === true) g.new_count++;
  const d = p.days_left === null || p.days_left === undefined ? 9999 : Number(p.days_left);
  if (Number.isFinite(d) && d < g.min_days) g.min_days = d;
}

// Most urgent supplier first, so the top of the message is where you start.
return order
  .map(function (k) { return groups.get(k); })
  .sort(function (a, b) { return a.min_days - b.min_days; })
  .map(function (g) { return { json: g }; });

// One message for the whole sheet: a burst of Telegram sends gets rate-limited,
// and a single digest is what a person can act on at 07:00.
const cfg = $('CONFIG').first().json;
const ringkas = $('Compare with Last Run').first().json;
const grup = $input.all().map(function (i) { return i.json; });

const judul = ringkas.new_count > 0
  ? 'Low stock: ' + ringkas.new_count + ' new, ' + ringkas.ongoing_count + ' ongoing'
  : 'Low stock: ' + ringkas.ongoing_count + ' ongoing, nothing new';

// The reason is only worth a line when the headline does not already say it.
const keterangan = /new item/.test(String(ringkas.reason)) ? '' : '(' + ringkas.reason + ')';

const blok = grup.map(function (g) {
  const lines = g.rows.map(function (r) {
    const left = r.days_left === null || r.days_left === undefined
      ? 'no usage data'
      : r.days_left + 'd left';
    const tanda = r.is_new ? 'NEW ' : '';
    return '- ' + tanda + r.item + ' (' + r.sku + '): ' + r.stock + ' of ' +
      r.reorder_point + ', ' + left + ', order ' + r.suggested_order;
  });
  return g.supplier + '\n' + lines.join('\n');
});

const teks = judul + (keterangan ? '\n' + keterangan : '') + '\n\n' + blok.join('\n\n');

return [{
  json: {
    chat_id: cfg.chat_id,
    should_send: ringkas.should_send === true,
    text: teks
  }
}];

// Written only on the send path. Static data is per workflow, so a second
// workflow using the same sheet keeps its own memory.
const store = $getWorkflowStaticData('global');
const skus = $('Split Items').all()
  .map(function (i) { return String(i.json.sku || '').trim(); })
  .filter(Boolean);

store.known = skus;
store.last_sent = (typeof $now !== 'undefined' && $now && $now.toISODate)
  ? $now.toISODate()
  : new Date().toISOString().slice(0, 10);

return $input.all();
